<?php
/**
 * The shared SVG icon library.
 *
 * includes/icon-library/<kit>.php holds every icon of one kit as SVG markup,
 * generated by bin/build-icon-library.py. The free and PRO plugins ship the
 * same files (PRO copies them with bin/sync-from-free.sh), so an icon looks
 * the same in both and nothing goes missing when a site moves to PRO.
 *
 * Kits are loaded on first use, once per request.
 *
 * @package WPZOOM_Social_Icons
 */

// Exit if accessed directly.
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Class WPZOOM_Social_Icons_Library
 */
class WPZOOM_Social_Icons_Library {

	/**
	 * Kits loaded so far: kit => array( name => svg ).
	 *
	 * @var array
	 */
	private static $kits = array();

	/**
	 * Directory of the kit files.
	 *
	 * @return string
	 */
	public static function dir() {
		return dirname( __DIR__ ) . '/icon-library/';
	}

	/**
	 * All icons of a kit.
	 *
	 * @param string $kit Kit name, e.g. 'socicon' or 'fab'.
	 * @return array Icon name => SVG markup; empty for an unknown kit.
	 */
	public static function kit( $kit ) {
		if ( ! isset( self::$kits[ $kit ] ) ) {
			$file                = self::dir() . $kit . '.php';
			self::$kits[ $kit ] = preg_match( '/^[a-z0-9-]+$/', $kit ) && is_readable( $file ) ? (array) include $file : array();
		}
		return self::$kits[ $kit ];
	}

	/**
	 * One icon's SVG markup.
	 *
	 * @param string $kit  Kit name.
	 * @param string $name Icon name.
	 * @return string SVG markup, or '' when the library has no such icon.
	 */
	public static function svg( $kit, $name ) {
		$icons = self::kit( $kit );
		return isset( $icons[ $name ] ) ? $icons[ $name ] : '';
	}

	/**
	 * Vertical metrics of the fonts the kits were drawn from: units per em,
	 * ascent, descent. An SVG extracted from a font keeps the font's units in
	 * its viewBox, so these place it exactly where the glyph used to sit.
	 *
	 * @var array
	 */
	private static $metrics = array(
		'socicon'     => array( 1024, 960, -64 ),
		'genericon'   => array( 2048, 2048, 0 ),
		'academicons' => array( 512, 440, -64 ),
		'dashicons'   => array( 512, 512, 0 ),
		'fab'         => array( 512, 448, -64 ),
		'far'         => array( 512, 448, -64 ),
		'fas'         => array( 512, 448, -64 ),
		'fa'          => array( 1792, 1536, -256 ),
	);

	/**
	 * An icon's SVG ready to place inline where the font glyph used to be.
	 *
	 * Sized in em and moved below the baseline like the glyph, painted with
	 * the text color, and hidden from assistive technology (the link around
	 * it carries the label). Size and color are attributes, so the icon is
	 * right even before any stylesheet loads.
	 *
	 * @param string $kit  Kit name.
	 * @param string $name Icon name.
	 * @return string SVG markup, or '' when the library has no such icon.
	 */
	public static function inline_svg( $kit, $name ) {
		$svg = self::svg( $kit, $name );
		if ( '' === $svg || ! preg_match( '/<svg\b[^>]*>/', $svg, $open ) ) {
			return '';
		}

		$width  = 1;
		$height = 1;
		$shift  = 0;
		if ( preg_match( '/viewBox="\s*[-\d.]+[\s,]+[-\d.]+[\s,]+([\d.]+)[\s,]+([\d.]+)\s*"/', $open[0], $box ) && $box[2] > 0 ) {
			list( $upm, $ascent, $descent ) = isset( self::$metrics[ $kit ] ) ? self::$metrics[ $kit ] : array( 0, 0, 0 );
			if ( $upm && abs( (float) $box[2] - ( $ascent - $descent ) ) < 1 ) {
				// Drawn in the font's own units.
				$height = $box[2] / $upm;
				$width  = $box[1] / $upm;
				$shift  = $descent / $upm;
			} else {
				// Any other artwork: an em-tall square, like a font glyph.
				$width = $box[1] / $box[2];
				$shift = $upm ? $descent / $upm : 0;
			}
		}

		$tag = preg_replace( '/\s(?:width|height|class|id|role|aria-hidden|focusable|style|fill)="[^"]*"/', '', $open[0] );
		$tag = substr( $tag, 0, -1 ) . sprintf(
			' class="wpzoom-svg-icon" width="%sem" height="%sem" fill="currentColor" aria-hidden="true" focusable="false"%s>',
			self::number( $width ),
			self::number( $height ),
			$shift ? ' style="vertical-align:' . self::number( $shift ) . 'em"' : ''
		);

		$svg = str_replace( $open[0], $tag, $svg );
		return preg_replace( '#<title\b[^>]*>.*?</title>#s', '', $svg );
	}

	/**
	 * A length for an attribute: at most four decimals, no trailing zeros.
	 *
	 * @param float $value Number.
	 * @return string
	 */
	private static function number( $value ) {
		return rtrim( rtrim( sprintf( '%.4f', $value ), '0' ), '.' );
	}

	/**
	 * Icon data with each icon's SVG added under 'svg'.
	 *
	 * @param array $data      Kit => list of array( 'icon' => name, ... ).
	 * @param array $preferred Optional kit => name => SVG used before the
	 *                         library (PRO's own artwork, which it saves into
	 *                         posts and so has to keep).
	 * @return array The same data; an icon with no SVG anywhere gets no 'svg'.
	 */
	public static function with_svg( $data, $preferred = array() ) {
		foreach ( $data as $kit => $items ) {
			if ( ! is_array( $items ) ) {
				continue;
			}
			foreach ( $items as $i => $item ) {
				if ( ! is_array( $item ) || ! isset( $item['icon'] ) ) {
					continue;
				}
				$name = $item['icon'];
				$svg  = isset( $preferred[ $kit ][ $name ] ) ? $preferred[ $kit ][ $name ] : self::svg( $kit, $name );
				if ( '' !== $svg ) {
					$data[ $kit ][ $i ]['svg'] = $svg;
				}
			}
		}
		return $data;
	}
}
